extern "C" const uint32_t g_duck_import_count = 239;

/* Sentinel guest-address base: a region the game never executes from.
 * sentinel_i = SENTINEL_BASE + i; the i-th import's OPD lives at
 * OPD_BASE + i*8. Both sit in committed scratch above the heap. */
#define DUCK_SENTINEL_BASE 0x3F000000u
#define DUCK_OPD_BASE      0x3E000000u

extern "C" uint32_t duck_import_nid_for_sentinel(uint32_t sentinel) {
    uint32_t i = sentinel - DUCK_SENTINEL_BASE;
    if (i < g_duck_import_count) return g_duck_imports[i].nid;
    return 0;
}
extern "C" const char* duck_import_name_for_sentinel(uint32_t sentinel) {
    uint32_t i = sentinel - DUCK_SENTINEL_BASE;
    if (i < g_duck_import_count) return g_duck_imports[i].name;
    return "?";
}

/* Install the import table: synthesize an OPD per import and repoint its
   data-segment slot at it. Sentinels are resolved by an O(1) range check
   in ps3_indirect_call (not the hash table). Call AFTER elf_load_segments
   (slots live in the data seg). */
extern "C" void duck_install_imports(void) {
    for (uint32_t i = 0; i < g_duck_import_count; i++) {
        uint32_t opd      = DUCK_OPD_BASE + i * 8;
        uint32_t sentinel = DUCK_SENTINEL_BASE + i;
        vm_write32(opd + 0, sentinel);             /* OPD.entry */
        vm_write32(opd + 4, 0);                    /* OPD.toc   */
        vm_write32(g_duck_imports[i].slot_va, opd);/* slot -> OPD */
    }
    fprintf(stderr, "[import] installed %u firmware imports\n", g_duck_import_count);
}
